    check("missing and corrupt settings fall back to safe defaults",[&]{auto missing=artifacts/L"missing-settings.json";std::filesystem::remove(missing);aoe::ManagerSettings loaded;std::string diagnostic;Require(aoe::LoadSettings(missing,loaded,diagnostic)&&loaded.initialCalls==2&&!loaded.autoAttach&&!loaded.autoArm&&!loaded.startWithWindows,"missing defaults");auto corrupt=artifacts/L"corrupt-settings.json";std::ofstream(corrupt)<<"{ definitely not json";loaded.initialCalls=100;Require(aoe::LoadSettings(corrupt,loaded,diagnostic)&&loaded.initialCalls==2&&!loaded.autoAttach,"corrupt defaults");});
    check("settings enforce Initial Calls minimum and maximum",[]{auto low=aoe::SafeDefaultSettings();low.initialCalls=0;Require(!aoe::ValidateSettings(low)&&low.initialCalls==2,"zero reset");auto high=aoe::SafeDefaultSettings();high.initialCalls=101;Require(!aoe::ValidateSettings(high)&&high.initialCalls==2,"over maximum reset");auto min=aoe::SafeDefaultSettings();min.initialCalls=1;auto max=aoe::SafeDefaultSettings();max.initialCalls=100;Require(aoe::ValidateSettings(min)&&aoe::ValidateSettings(max),"1 and 100 accepted");});
