    check("current profile carries recovered per-build layout and differential anchors",[&]{aoe::BuildProfile profile;std::filesystem::path path;std::string error;Require(aoe::SelectBuildProfile(profileDir,aoe::CurrentPatchHash,profile,path,error),error);const auto& r=profile.runtime;Require(r.targetInspectorAvailable&&r.targetVectorOffset==0x660&&r.actorIdOffset==0x768&&r.actorTypeOffset==0x7E1&&r.actorEligibilityOffset==0x7CA&&r.actorStatusOffset==0x7E4&&r.actorPositionOffset==0xB0&&r.actorWorldLinkOffset==0x1390&&r.actorWorldLinkOwnerOffset==0x1380&&r.actorWorldPositionOffset==0x70,"recovered layout");Require(r.initialPrepRva==0x7F2760&&r.initialCallRva==0x7F277D&&r.initialReturnRva==0x7F2782&&r.differentialParsedRva==0x6CB73&&r.sharedWorkerRva==0x7BC4C0&&r.typedActorLookupRva==0x7BAF60&&r.producerCallRva==0x7BC817&&r.producerRva==0x99150,"recovered differential and replay chain");Require(r.gameContextPointerRva==0xE6C9C0&&r.selectedTargetOffset==0x2318&&r.selectedTargetWriterRva==0x7F6411&&r.selectedTargetWriterBytes==std::vector<uint8_t>({0x4C,0x89,0x83,0x18,0x23,0x00,0x00})&&r.selectedTargetReaderRvas==std::vector<uint64_t>({0x799891,0x7D7C77}),"selected-target static candidate path and writer fingerprint");Require(r.differentialParsedBytes==std::vector<uint8_t>({0x66,0x47,0x39,0x74,0x6F,0x3C}),"parsed boundary fingerprint");Require(r.actorTreeOffsets[2]==0x1120&&r.targetRecordBytes==8&&r.targetMaximumEntries==32,"record and resolver layout");});
